<template><section v-loading="loading" class="client-cohort-settings" data-dialog-field-search-label="新老客户及订单数"><strong>新老客户</strong><p>{{state?.cohort==='old'?'老客户':'新客户'}} · {{state?.order_count||0}} 个订单 · 首次订单：{{state?.first_order_date||'暂无订单'}}<span v-if="state?.override"> · 手动设置</span></p><small>跨笔译、口译、标注、招聘统计：至少2个母订单，或首次订单距今满3个月为老客户。按日期筛选时临时按日期范围判断，不受手动设置影响。</small><p v-if="state?.reason">最近调整原因：{{state.reason}}</p><details v-if="state?.history?.length"><summary>新老客户调整记录（{{state.history.length}}）</summary><p v-for="(item,index) in state.history" :key="index">{{formatBusinessDateTimeMinute(item.at)}} · {{item.after==='new'?'新客户':item.after==='old'?'老客户':'自动判断'}} · {{item.reason}}</p></details><template v-if="canWrite"><el-form-item label="新老客户判断方式"><el-select v-model="cohort" aria-label="新老客户判断方式"><el-option label="系统自动判断" value="auto"/><el-option label="手动设为新客户" value="new"/><el-option label="手动设为老客户" value="old"/></el-select></el-form-item><el-form-item label="调整原因"><el-input v-model="reason" type="textarea" :rows="2" maxlength="2000" placeholder="手动调整或恢复自动判断时，请填写原因"/></el-form-item><el-button :loading="saving" @click="save">保存新老客户设置</el-button></template><el-alert v-if="error" :title="error" type="error" :closable="false"/></section></template>
<script setup>
import {ref,watch} from 'vue'
import api from '@/api'
import {formatBusinessDateTimeMinute} from '@/utils/dateTime'
import {ElMessage} from 'element-plus'
const props=defineProps({clientId:[String,Number],canWrite:Boolean}),emit=defineEmits(['saved'])
const state=ref(null),cohort=ref('auto'),reason=ref(''),loading=ref(false),saving=ref(false),error=ref('')
watch(()=>props.clientId,async(id,_,onCleanup)=>{if(!id)return;const request=new AbortController();onCleanup(()=>request.abort());loading.value=true;try{state.value=await api.get(`/clients/${id}/cohort`,{signal:request.signal});cohort.value=state.value.override||'auto';reason.value='';error.value=''}catch(e){if(!request.signal.aborted)error.value=e.detail||'新老客户读取失败'}finally{if(!request.signal.aborted)loading.value=false}},{immediate:true})
async function save(){if(!reason.value.trim()){ElMessage.warning('请填写调整原因');return}saving.value=true;error.value='';try{state.value=await api.put(`/clients/${props.clientId}/cohort`,{cohort:cohort.value==='auto'?null:cohort.value,reason:reason.value.trim(),expected_updated_at:state.value?.updated_at||null});reason.value='';emit('saved',state.value);ElMessage.success('新老客户设置已保存')}catch(e){error.value=e.detail||'保存失败'}finally{saving.value=false}}
</script>
<style scoped>.client-cohort-settings{padding:14px;border:1px solid var(--el-border-color);border-radius:8px;margin:14px 0}.client-cohort-settings small{display:block;color:var(--el-text-color-secondary);line-height:1.7;margin-bottom:10px}</style>
